import { h } from 'vue';
import App from '../App.vue';
import View from '../components/GeneratedViewPage.vue';
import Home from '../components/HomeConceptPage.vue';
import Palette from '../components/SearchPalette.vue';
import EmbeddingMap from '../components/EmbeddingMap.vue';
import snapshot from '../data/archiveDemoView.json';
import searchItems from '../data/archiveDemoSearch.json';

// Keep the production render functions, scoped styles and responsive rules.
// Preview components replace service/lifecycle work with a supplied clock.
// This module is loaded only by the isolated, non-interactive preview document.
function presentation(component, options) {
  const result = { ...component };
  for (const key of ['mixins', 'extends', 'watch', 'created', 'mounted', 'beforeMount', 'beforeUnmount', 'unmounted', 'beforeRouteLeave', 'beforeRouteUpdate']) delete result[key];
  return { ...result, inject: ['previewClock'], ...options,
    computed: { ...component.computed, ...options.computed },
    methods: { ...component.methods, ...options.methods },
  };
}

const question = snapshot.view.question;
const answer = `${snapshot.view.sections[0].blocks[0].text} [1]`;
const sources = [snapshot.sources[0]].map((source, index) => ({ ...source, id: index + 1 }));
const offer = { title: snapshot.view.title, description: 'Explore the places, memories and original writing.' };
const empty = { render: () => h('div') };
const PreviewMap = {
  ...EmbeddingMap, inject: ['previewClock'],
  watch: { ...EmbeddingMap.watch, 'previewClock.state'() { this.syncPreviewProjection(); } },
  methods: { ...EmbeddingMap.methods,
    start3dMotion() { this.syncPreviewProjection(); },
    syncPreviewProjection() {
      if (this.viewMode !== '3d' || !this._points?.length || !this._w) return;
      this._yaw = -.72 + this.previewClock.state.time * .00016;
      this.updateProjection(); this.draw();
    },
  },
};

export const PreviewHome = presentation(Home, {
  name: 'ArchivePreviewHome',
  components: { ...Home.components, AboutTab: empty, EmbeddingMap: PreviewMap },
  data() {
    return {
      entranceMode: 'settled', entrancePending: false,
      mobileViewport: window.innerWidth <= 760, desktopHover: false,
      askText: '', askOpen: false, askBusy: false, askAnswer: '', submittedQuestion: '', askSources: sources,
      askInputActive: false, askTurn: 0, askError: '', askComposing: false,
      sceneMasked: false, sceneMuted: true, viewRouting: 'offer',
      homeViewError: '', viewSession: null, askMapVisible: false, askMapHits: [], askMapLabel: '', askMapFinalized: false,
      hoveredSourceId: null, previewStyle: null, activeChapter: 'story-hello',
      chapters: [
        { id: 'story-hello', label: 'Hello' }, { id: 'story-now', label: 'Now' },
        { id: 'story-about', label: 'About' }, { id: 'story-research', label: 'Research' },
        { id: 'story-builds', label: 'Builds' }, { id: 'story-life', label: 'Life' },
        { id: 'story-contact', label: 'Contact' }, { id: 'story-index', label: 'Index' },
      ], siteIndexItems: [],
    };
  },
  computed: {
    homeViewBusy() { return this.previewClock.state.phase === 'composing'; },
    homeViewStartedAt() { return this.previewClock.composeStartedAt; },
    askInputLocked() { return this.askBusy || this.homeViewBusy; },
    citedSources() { return this.askAnswer ? sources : []; },
    followUps() { return []; },
    viewOffer() { return offer; },
    canReturnToView() { return false; },
    sourcePreview() { return null; },
  },
  watch: {
    'previewClock.state': { immediate: true, handler(state) {
      this.askOpen = this.previewClock.scene === 'home' && ['thinking', 'answer', 'composing'].includes(state.phase);
      this.askBusy = state.phase === 'thinking';
      this.askText = this.askOpen ? '' : state.typed;
      this.submittedQuestion = this.askOpen ? question : '';
      this.askAnswer = this.askOpen && !this.askBusy ? answer : '';
    } },
  },
  mounted() {
    const layout = () => this.syncMobileHeroLayout();
    this._previewResize = new ResizeObserver(layout);
    this._previewResize.observe(this.$el);
    document.fonts.ready.then(layout);
    layout();
  },
  beforeUnmount() { this._previewResize?.disconnect(); this._homeAnims?.forEach(animation => animation.stop()); },
});

export const PreviewPalette = presentation(Palette, {
  name: 'ArchivePreviewPalette',
  components: { ...Palette.components, EmbeddingMap: PreviewMap },
  data() {
    const data = Palette.data.call(this);
    return { ...data, loaded: true, viewOfferVisible: true, askSources: sources,
      recentSharedViews: [{ id: snapshot.id, title: snapshot.view.title, question }],
    };
  },
  computed: {
    askReady() { return true; },
    canReturnToView() { return false; },
    viewOffer() { return offer; },
    askFollowUpQuestions() { return []; },
    results() { return this.mode === 'search' ? searchItems : []; },
  },
  watch: {
    'previewClock.state': { immediate: true, handler(state) {
      this.open = this.previewClock.scene === 'palette' && state.open;
      this.mode = state.mode || 'search';
      this.query = this.mode === 'search' ? 'Shanghai' : this.mode === 'ask' ? question : '';
      this.askAnswer = answer;
      this.mobileModeMenuOpen = state.modeMenu;
    } },
  },
  mounted() { this._spAnims = new Set(); },
  beforeUnmount() { this._spAnims?.forEach(animation => animation.stop()); },
});

export const PreviewView = presentation(View, {
  name: 'ArchivePreviewView',
  data() {
    return { ...View.data.call(this), view: snapshot.view,
      sourcesById: new Map(snapshot.sources.map(source => [source.source_id, source])),
      currentSourcesById: new Map(snapshot.sources.map(source => [source.source_id, source])),
      sourcesLoading: false, shareId: snapshot.id, shareVisibility: 'public',
    };
  },
  computed: {
    showBackLink() { return true; },
    originLabel() { return 'Home'; },
    embedded() { return false; },
  },
});

export const PreviewApp = presentation(App, {
  name: 'ArchivePreviewApp',
  components: { ...App.components, SearchPalette: PreviewPalette },
  data() {
    return { ...App.data.call(this), homeArrivalPending: false, initialChromeReady: true };
  },
  computed: { showScrollProgress() { return false; } },
  methods: {
    // The memory router belongs to the presentation clock, with no history,
    // saved positions, analytics, global shortcuts or visitor state.
    beforeRouteEnter() {}, finishRouteProgressTransition() {},
  },
});
